// ---------------------------------------------------------------- sequence
// Insert the `sep` trial(s) after every n trials of `main` (not after the last one).
// Defined here rather than relying on the Farm's sepWithN, which stock Ibex lacks.
function BreakEvery(sep, main, n) {
    this.args = [sep, main];
    this.run = function (arrays) {
        const sep = arrays[0], main = arrays[1], out = [];
        main.forEach((m, i) => {
            out.push(m);
            if ((i + 1) % n === 0 && i < main.length - 1) sep.forEach(s => out.push(s));
        });
        return out;
    };
}
function breakEvery(sep, main, n) { return new BreakEvery(sep, main, n); }

SetCounter("counter", "inc", 1);   // advance the Latin-square counter when a participant starts

Sequence(
    "counter",
    "welcome", "demographics",
    "instructions",
    "practice",
    "begin",
    // Plain random order of all critical + filler trials. KAD's rshuffle(startsWith("Exp")) did the
    // same: rshuffle with a single predicate is just randomize().
    breakEvery("break", randomize(startsWith("exp-")), CFG.breakEvery),
    "debrief",
    "send",
    "end"
);

// Logged on every result line.
