// ---------------------------------------------------------------- look
// Matches the legacy-Ibex look of the lab's Farm projects (e.g. farm.pcibex.net/p/QsqOnM): the Farm's
// default css_includes give the white page, serif text, progress bar and 40em PennController column;
// the positions below reproduce DashedAcceptabilityJudgment's layout (words and question near the top,
// Yes/No in small bordered boxes, "→ Click here to continue" links instead of buttons).
// Pixel positions are from the top of the page, as in legacy Ibex (measured at the Farm's 16px base).
const WORD_POS = ["center at 50vw", "middle at 240px"];        // where DashedSentence 'in place' words sit
const QUESTION_POS = ["center at 50vw", "top at 207px"];
const ANSWER_POS = ["center at 50vw", "top at 279px"];
const WORD_CSS = {"font-size": CFG.fontSize, "white-space": "nowrap"};
const BOX_CSS = {"border": "1px solid #9ea4b1", "width": "32px", "height": "32px", "padding-top": "8px",
                 "text-align": "center", "color": "blue", "cursor": "pointer", "font-size": "16px"};
const LINK_CSS = {"background": "none", "border": "none", "padding": "0", "margin": "1em 0 0 0",
                  "color": "blue", "cursor": "pointer", "font": "inherit", "font-size": "16px",
                  "text-align": "left"};
const TEXT_CSS = {"font-size": "16px", "width": "40em", "text-align": "left"};

// Hover underline for the continue links, as with Ibex's Message-continue-link.
$("head").append("<style>.PennController-continue:hover{text-decoration:underline}</style>");

// A "→ Click here to continue" link (a Button styled as a link, so .wait() and tests still work).
function continueLink(text) {
    return newButton("continue", text).css(LINK_CSS);
}

// Fixation cross, then the sentence word by word in place.
// Like legacy DashedSentence 'in place': each word for wordTime ms, a blank screen
// of pauseTime ms between words, and the question right after the last word.
function rsvp(sentence) {
    const words = sentence.trim().split(/\s+/);
    const cmds = [
        newText("fix", "+").css(WORD_CSS).print(...WORD_POS),
        newTimer("fixT", CFG.fixationTime).start().wait(),
        getText("fix").remove()
    ];
    words.forEach((w, i) => {
        cmds.push(
            newText("w" + i, w).css(WORD_CSS).print(...WORD_POS),
            newTimer("wT" + i, CFG.wordTime).start().wait(),
            getText("w" + i).remove()
        );
        if (i < words.length - 1 && CFG.pauseTime > 0)
            cmds.push(newTimer("pT" + i, CFG.pauseTime).start().wait());
    });
    return cmds;
}

// Yes/No judgment under a deadline. Logs response (yes/no/NA), RT (ms from question
// onset; NA on timeout) and timedout (yes/no). Keys or mouse clicks both work.
function judgment() {
    return [
        newVar("response", "NA").global(),   // global so the trial can .log() them
        newVar("RT", "NA").global(),
        newVar("timedout", "no").global(),
        getVar("response").set("NA"), getVar("RT").set("NA"), getVar("timedout").set("no"),   // reset per trial
        newTimer("deadline", CFG.deadline),
        // As legacy Question with presentHorizontally: the question at 2em, then Yes and No in
        // small bordered boxes side by side (16px gap). An optional key hint goes below them.
        newText("question", CFG.question).css({"font-size": CFG.fontSize, "white-space": "nowrap"})
            .print(...QUESTION_POS),
        newText("yes", CFG.yesLabel).css(BOX_CSS),
        newText("no", CFG.noLabel).css(BOX_CSS),
        newText("keyhint", CFG.keyHint).css({"font-size": "small", "font-style": "italic", "white-space": "nowrap"}),
        newCanvas("answer", 84, 90)
            .add(0, 0, getText("yes"))
            .add(50, 0, getText("no"))
            .add("center at 50%", 60, CFG.keyHint ? getText("keyhint") : newText("nohint", ""))
            .print(...ANSWER_POS),
        newSelector("judgment")
            .add(getText("yes"), getText("no"))
            .keys(CFG.yesKey, CFG.noKey)
            .once()
            .log()
            .callback(
                getVar("RT").set(v => Date.now() - v),
                getTimer("deadline").stop()
            ),
        getVar("RT").set(v => Date.now()),
        getTimer("deadline").start().wait(),
        getSelector("judgment").disable(),   // no late answers after the deadline
        getSelector("judgment")
            .test.selected(getText("yes"))
            .success(getVar("response").set("yes"))
            .failure(
                getSelector("judgment").test.selected(getText("no"))
                    .success(getVar("response").set("no"))
                    .failure(
                        getVar("timedout").set("yes"),
                        getVar("RT").set("NA"),
                        getCanvas("answer").remove(),
                        getText("question").remove(),
                        newText("timeoutMsg", CFG.timeoutMessage).css({"font-size": "16px", "white-space": "nowrap"}).print(...QUESTION_POS),
                        newTimer("timeoutT", CFG.timeoutMessageTime).start().wait()
                    )
            ),
        getCanvas("answer").remove(),
        getText("question").remove()
    ];
}

// A judgment trial; logs the per-row columns named in `cols` plus the response vars.
function judgmentTrial(label, row, cols) {
    let t = newTrial(label, ...rsvp(row[CFG.sentenceColumn]), ...judgment())
        .log("response", getVar("response"))
        .log("RT", getVar("RT"))
        .log("timedout", getVar("timedout"));
    cols.forEach(c => { t = t.log(c, row[c]); });
    return t;
}

// An HTML form page that must be completed (class="obligatory" fields) before going on.
// The chunk's own <div style="width: 50%; margin: 0 auto"> is meant for the full page width, as in
// legacy Form, so the Html element is widened from the 40em PennController column to the viewport.
// `after` runs once the page is printed (used to prefill the Prolific ID).
const FORM_CSS = {"width": "100vw", "flex-shrink": "0", "margin-left": "calc(20em - 50vw)", "font-size": "16px"};
function formPage(label, file, ...after) {
    return newTrial(label,
        newHtml("form", file).css(FORM_CSS).log().print(),
        ...after,
        continueLink("→ Click here to continue").print()
            .wait(getHtml("form").test.complete().failure(getHtml("form").warn()))
    );
}

// Legacy Message: left-aligned text in the 40em column, then a "→ Click here to continue." link.
function message(label, html, linkText) {
    return newTrial(label,
        newText("msg", html).css(TEXT_CSS).print(),
        continueLink(linkText || "→ Click here to continue.").print().wait()
    );
}

// ---------------------------------------------------------------- trials
