formPage("instructions", "practice2.html");
formPage("instructions", "practice3.html");

// Practice: optional message before each sentence, then the sentence.
CFG.practice.forEach(p => {
    if (p.before) message("practice", p.before);
    judgmentTrial("practice", {[CFG.sentenceColumn]: p.sentence, practice_id: p.id}, ["practice_id"]);
});
message("begin", CFG.beginMessage);

